/** Characters for random passwords, without easily confused ones (0/O, 1/l/I). */
const PASSWORD_CHARS = 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789';

/**
 * Make a random password.
 *
 * @param {number} length
 * @returns {string}
 */
const randomPassword = (length = 6) => {
    const values = new Uint32Array(length);
    window.crypto.getRandomValues(values);
    return Array.from(values, (v) => PASSWORD_CHARS[v % PASSWORD_CHARS.length]).join('');
};

/**
 * Highlight a cell whose value differs from what was loaded.
 *
 * @param {HTMLInputElement|HTMLSelectElement} input
 */
const refreshChanged = (input) => {
    input.closest('td').classList.toggle('table-warning', input.value !== input.dataset.original);
};

/**
 * Set an input's value as if the user typed it.
 *
 * @param {HTMLInputElement|HTMLSelectElement} input
 * @param {string} value
 */
const setValue = (input, value) => {
    input.value = value;
    input.classList.remove('is-invalid');
    refreshChanged(input);
    markFormChangedFromNode(input);
};

/** Review time bits, as in mod_quiz\question\display_options. */
const DURING = 0x10000;
const AFTER_CLOSE = 0x00010;

/** Review options that need "The attempt" at the same time (except during the attempt). */
const NEEDS_ATTEMPT = ['reviewcorrectness', 'reviewspecificfeedback', 'reviewgeneralfeedback', 'reviewrightanswer'];

/**
 * Apply the quiz settings form's review option rules (mirrors updater::normalise_review()).
 *
 * @param {Object<string, number>} review field => bits
 * @param {string[]} unusedDuring fields the question behaviour doesn't use during the attempt
 * @returns {Object<string, number>}
 */
const normaliseReview = (review, unusedDuring) => {
    review.reviewattempt |= DURING;
    review.reviewoverallfeedback &= ~DURING;
    unusedDuring.forEach((field) => {
        if (field in review) {
            review[field] &= ~DURING;
        }
    });
    review.reviewmarks &= review.reviewmaxmarks;
    NEEDS_ATTEMPT.forEach((field) => {
        review[field] &= review.reviewattempt | DURING;
    });
    return review;
};

/**
 * Whether a review checkbox can be changed, following the quiz settings form.
 *
 * @param {string} field
 * @param {number} bit
 * @param {Object<string, number>} review
 * @param {string[]} unusedDuring
 * @param {boolean} hasClose whether the quiz has a close date
 * @returns {boolean}
 */
const reviewLocked = (field, bit, review, unusedDuring, hasClose) => {
    if (bit === DURING && (['reviewattempt', 'reviewoverallfeedback'].includes(field) || unusedDuring.includes(field))) {
        return true;
    }
    if (bit === AFTER_CLOSE && !hasClose) {
        return true;
    }
    if (field === 'reviewmarks' && !(review.reviewmaxmarks & bit)) {
        return true;
    }
    return bit !== DURING && NEEDS_ATTEMPT.includes(field) && !(review.reviewattempt & bit);
};

/**
 * Escape text for use in HTML.
 *
 * @param {string} text
 * @returns {string}
 */
const escapeHtml = (text) => {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
};

/**
 * The current time as a datetime-local value, in the user's Moodle timezone (which the server parses dates in).
 *
 * @param {string} timezone IANA timezone name
 * @returns {string} e.g. 2026-10-02T14:05
 */
const nowInTimezone = (timezone) => {
    let parts;
    try {
        parts = new Intl.DateTimeFormat('en-GB', {
            timeZone: timezone, hourCycle: 'h23',
            year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit',
        }).formatToParts(new Date());
    } catch (e) {
        // Unknown timezone name: fall back to the browser's own.
        parts = new Intl.DateTimeFormat('en-GB', {
            hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit',
        }).formatToParts(new Date());
    }
    const part = (type) => parts.find((p) => p.type === type).value;
    return `${part('year')}-${part('month')}-${part('day')}T${part('hour')}:${part('minute')}`;
};

/**
 * Initialise the page.
 *
 * @param {string} formId
 */
export const init = (formId) => {
    const form = document.getElementById(formId);
    if (!form) {
        return;
    }
    watchFormById(formId);

    const fieldSelect = form.querySelector('[data-action="bulkfield"]');
    const valueLabel = form.querySelector('[data-region="bulkvaluelabel"]');
    const valueControls = [...form.querySelectorAll('[data-bulkvalue]')];
    const valueControl = () => valueControls.find((control) => control.dataset.bulkvalue === fieldSelect.value);
    const randomButton = form.querySelector('[data-action="bulkrandom"]');
    const selectAll = form.querySelector('[data-action="selectall"]');
    // Only quizzes left visible by the filter can be selected or changed in bulk.
    const rowBoxes = () => [...form.querySelectorAll('[data-action="select"]')].filter((box) => !box.closest('tr').hidden);
    const selectedRows = () => rowBoxes().filter((box) => box.checked).map((box) => box.closest('tr'));

    const syncToolbar = () => {
        const active = valueControl();
        valueControls.forEach((control) => {
            control.hidden = control !== active;
        });
        valueLabel.htmlFor = active.id;
        randomButton.hidden = fieldSelect.value !== 'password';
    };
    fieldSelect.addEventListener('change', syncToolbar);
    syncToolbar();

    const requireSelection = async() => {
        const rows = selectedRows();
        if (!rows.length) {
            addToast(await getString('selectfirst', 'local_quizbulkedit'), {type: 'warning'});
        }
        return rows;
    };

    form.querySelector('[data-action="bulkapply"]').addEventListener('click', async() => {
        const field = fieldSelect.value;
        const value = valueControl().value;
        (await requireSelection()).forEach((row) => {
            if (field === 'review') {
                copyReview(row, value);
                return;
            }
            if (field === 'all') {
                copyAll(row, value);
                return;
            }
            const control = row.querySelector(`[data-field="${field}"]`);
            // E.g. a quiz can't copy SEB settings from itself, so that option is missing from its own list.
            const allowed = control.tagName !== 'SELECT' || [...control.options].some((option) => option.value === value);
            if (!control.disabled && allowed) {
                setValue(control, value);
                if (field === 'timeclose') {
                    syncReview(row);
                }
            }
        });
    });

    randomButton.addEventListener('click', async() => {
        (await requireSelection()).forEach((row) => {
            setValue(row.querySelector('input[data-field="password"]'), randomPassword());
        });
    });

    const quizRows = [...form.querySelectorAll('tr[data-quizid]')];
    const reviewRow = (row) => form.querySelector(`tr[data-reviewfor="${row.dataset.quizid}"]`);
    const quizRow = (quizid) => form.querySelector(`tr[data-quizid="${quizid}"]`);
    const reviewInputs = (row) => [...row.querySelectorAll('input[data-review]')];
    const getReview = (row) => Object.fromEntries(reviewInputs(row).map((input) => [input.dataset.field, Number(input.value)]));
    const unusedDuring = (row) => reviewRow(row).dataset.unusedduring.split(' ').filter((field) => field.length);

    // Show the review hidden inputs in the grid: ticks, locked boxes and change highlights.
    const syncReview = (row) => {
        const review = getReview(row);
        const hasClose = row.querySelector('input[data-field="timeclose"]').value !== '';
        const originals = Object.fromEntries(
            reviewInputs(row).map((input) => [input.dataset.field, Number(input.dataset.original)])
        );
        reviewRow(row).querySelectorAll('input[data-reviewfield]').forEach((box) => {
            const field = box.dataset.reviewfield;
            const bit = Number(box.dataset.bit);
            box.checked = Boolean(review[field] & bit);
            box.disabled = reviewLocked(field, bit, review, unusedDuring(row), hasClose);
            box.closest('td').classList.toggle('table-warning', (review[field] & bit) !== (originals[field] & bit));
        });
        row.querySelector('td[data-cell="review"]').classList.toggle('table-warning',
            reviewInputs(row).some((input) => input.value !== input.dataset.original));
    };

    const setReview = (row, review) => {
        normaliseReview(review, unusedDuring(row));
        reviewInputs(row).forEach((input) => {
            input.value = String(review[input.dataset.field]);
        });
        markFormChangedFromNode(reviewInputs(row)[0]);
        syncReview(row);
    };

    const copyReview = (row, sourceId) => {
        const source = quizRow(sourceId);
        if (source && source !== row) {
            setReview(row, getReview(source));
        }
    };
    quizRows.forEach(syncReview);
    const gridStrings = JSON.parse(form.querySelector('table[data-reviewgrid]').dataset.reviewgrid);
    const fill = (pattern, values) => pattern.replace(/\{(\w+)\}/g, (match, key) => values[key] ?? match);

    // Build a quiz's review options grid the first time it is shown.
    const buildGrid = (row) => {
        const cell = reviewRow(row).querySelector('[data-region="reviewdetail"]');
        if (cell.firstChild) {
            return;
        }
        const quiz = row.querySelector('.local-quizbulkedit-sticky2 a').textContent.trim();
        const table = document.createElement('table');
        table.className = 'table table-sm table-bordered w-auto mb-1 small';
        table.createCaption().textContent = fill(gridStrings.caption, {quiz});
        table.caption.className = 'caption-top pb-1';
        const head = table.createTHead().insertRow();
        head.appendChild(document.createElement('td'));
        gridStrings.times.forEach((time) => {
            const th = document.createElement('th');
            th.scope = 'col';
            th.className = 'text-center';
            th.textContent = time.label;
            head.appendChild(th);
        });
        const body = table.createTBody();
        gridStrings.items.forEach((item) => {
            const tr = body.insertRow();
            const th = document.createElement('th');
            th.scope = 'row';
            th.className = 'fw-normal';
            th.textContent = item.label;
            tr.appendChild(th);
            gridStrings.times.forEach((time) => {
                const td = tr.insertCell();
                td.className = 'text-center';
                const box = document.createElement('input');
                box.type = 'checkbox';
                box.className = 'form-check-input';
                box.id = `local_quizbulkedit_${row.dataset.quizid}_${item.field}_${time.key}`;
                box.dataset.reviewfield = item.field;
                box.dataset.bit = time.bit;
                const label = document.createElement('label');
                label.htmlFor = box.id;
                label.className = 'visually-hidden';
                label.textContent = fill(gridStrings.checkbox, {option: item.label, when: time.label, quiz});
                td.append(box, label);
            });
        });
        cell.appendChild(table);
        syncReview(row);
    };

    const setReviewOpen = (row, open) => {
        if (open) {
            buildGrid(row);
        }
        reviewRow(row).hidden = !open || row.hidden;
        row.querySelector('[data-action="togglereview"]').setAttribute('aria-expanded', open ? 'true' : 'false');
    };
    const isReviewOpen = (row) => row.querySelector('[data-action="togglereview"]').getAttribute('aria-expanded') === 'true';

    const filterInput = document.querySelector('[data-action="filter"]');
    const filterValue = form.querySelector('[data-region="filtervalue"]');
    const filterCount = document.querySelector('[data-region="filtercount"]');
    const changedOnly = document.querySelector('[data-action="changedonly"]');
    const rowChanged = (row) => [...row.querySelectorAll('[data-original]')]
        .some((input) => input.value !== input.dataset.original);
    const applyFilter = async() => {
        const words = filterInput.value.toLowerCase().split(/\s+/).filter((word) => word.length);
        let shown = 0;
        quizRows.forEach((row) => {
            const text = row.dataset.search.toLowerCase();
            row.hidden = !words.every((word) => text.includes(word)) || (changedOnly.checked && !rowChanged(row));
            setReviewOpen(row, isReviewOpen(row));
            shown += row.hidden ? 0 : 1;
        });
        filterValue.value = filterInput.value;
        filterCount.textContent = words.length || changedOnly.checked ?
            await getString('filtercount', 'local_quizbulkedit', {shown, total: quizRows.length}) : '';
        const boxes = rowBoxes();
        selectAll.checked = boxes.length > 0 && boxes.every((box) => box.checked);
        selectAll.indeterminate = !selectAll.checked && boxes.some((box) => box.checked);
    };
    filterInput.addEventListener('input', applyFilter);
    changedOnly.addEventListener('change', applyFilter);
    filterInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            e.preventDefault();
        }
    });
    applyFilter();

    // Columns picker: show or hide columns, and remember the choice for next time.
    const columnsMenu = document.querySelector('[data-region="columns"]');
    const columnBoxes = [...columnsMenu.querySelectorAll('[data-column]')];
    const applyColumns = () => {
        const shown = columnBoxes.filter((box) => box.checked).map((box) => box.dataset.column);
        form.querySelectorAll('[data-col]').forEach((cell) => {
            cell.hidden = !shown.includes(cell.dataset.col);
        });
        form.querySelectorAll('[data-region="reviewdetail"]').forEach((cell) => {
            cell.colSpan = shown.length + 1;
        });
        // The bulk toolbar only offers the columns on show.
        [...fieldSelect.options].forEach((option) => {
            option.hidden = option.value !== 'all' && !shown.includes(option.value);
        });
        if (fieldSelect.selectedOptions[0]?.hidden) {
            const first = [...fieldSelect.options].find((option) => !option.hidden);
            if (first) {
                fieldSelect.value = first.value;
            }
            syncToolbar();
        }
        return shown;
    };
    // Uses the AJAX web service rather than the routed REST API, which needs web server rewrite rules.
    const saveColumns = (shown) => Ajax.call([{
        methodname: 'core_user_set_user_preferences',
        args: {preferences: [{name: 'local_quizbulkedit_columns', value: shown.join(',')}]},
    }])[0].catch(Notification.exception);
    columnsMenu.addEventListener('change', (e) => {
        if (e.target.dataset.column) {
            saveColumns(applyColumns());
        }
    });
    columnsMenu.querySelector('[data-action="defaultcolumns"]').addEventListener('click', () => {
        const defaults = columnsMenu.dataset.default.split(',');
        columnBoxes.forEach((box) => {
            box.checked = defaults.includes(box.dataset.column);
        });
        applyColumns();
        // An empty preference means "the defaults", so later default changes reach this user too.
        saveColumns([]);
    });

    form.addEventListener('click', (e) => {
        const toggle = e.target.closest('[data-action="togglereview"]');
        if (toggle) {
            const row = toggle.closest('tr');
            setReviewOpen(row, !isReviewOpen(row));
        } else if (e.target.closest('[data-action="togglereviewall"]')) {
            const visible = quizRows.filter((row) => !row.hidden);
            const open = !visible.every(isReviewOpen);
            visible.forEach((row) => setReviewOpen(row, open));
        }
    });

    selectAll.addEventListener('change', () => {
        rowBoxes().forEach((box) => {
            box.checked = selectAll.checked;
        });
    });
    form.addEventListener('change', (e) => {
        if (e.target.dataset.reviewfield) {
            const row = quizRow(e.target.closest('tr[data-reviewfor]').dataset.reviewfor);
            const review = getReview(row);
            const bit = Number(e.target.dataset.bit);
            review[e.target.dataset.reviewfield] = e.target.checked ?
                review[e.target.dataset.reviewfield] | bit : review[e.target.dataset.reviewfield] & ~bit;
            setReview(row, review);
        } else if (e.target.dataset.action === 'reviewcopy') {
            copyReview(e.target.closest('tr'), e.target.value);
            e.target.value = '';
        } else if (e.target.dataset.action === 'select') {
            const boxes = rowBoxes();
            selectAll.checked = boxes.every((box) => box.checked);
            selectAll.indeterminate = !selectAll.checked && boxes.some((box) => box.checked);
        }
    });

    form.addEventListener('input', (e) => {
        if (e.target.dataset.original !== undefined) {
            refreshChanged(e.target);
        }
        if (e.target.dataset.field === 'timeclose') {
            syncReview(e.target.closest('tr'));
        }
    });

    // Enter in a toolbar value box should apply, not submit the whole form.
    valueControls.forEach((control) => control.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            form.querySelector('[data-action="bulkapply"]').click();
        }
    }));

    // Copy every setting of another quiz, except its name, visibility and dates.
    const NOT_COPIED = ['name', 'visible', 'timeopen', 'timeclose'];
    const copyAll = (row, sourceId) => {
        const source = quizRow(sourceId);
        if (!source || source === row) {
            return;
        }
        source.querySelectorAll('[data-field][data-original]:not([data-review])').forEach((sourceControl) => {
            const field = sourceControl.dataset.field;
            const control = row.querySelector(`[data-field="${field}"]`);
            if (NOT_COPIED.includes(field) || !control || control.disabled) {
                return;
            }
            // Safe Exam Browser: copy the other quiz's setup, or turn it off.
            const value = field === 'seb' ?
                (sourceControl.dataset.original === '0' ? '0' : `q${sourceId}`) : sourceControl.value;
            if (control.tagName !== 'SELECT' || [...control.options].some((option) => option.value === value)) {
                setValue(control, value);
            }
        });
        copyReview(row, sourceId);
    };

    // Open now / Close now: set the date on the selected quizzes, then save (after the review pop-up).
    const setNow = async(field) => {
        const rows = await requireSelection();
        if (!rows.length) {
            return;
        }
        const now = nowInTimezone(form.dataset.timezone);
        rows.forEach((row) => {
            setValue(row.querySelector(`input[data-field="${field}"]`), now);
            // Closing now: an open date that isn't before now would be refused (close must be after open), and the
            // quiz is closed either way, so clear it. The review pop-up shows this.
            const open = row.querySelector('input[data-field="timeopen"]');
            if (field === 'timeclose' && open.value !== '' && open.value >= now) {
                setValue(open, '');
            }
            // Opening a hidden quiz now would still leave students unable to see it.
            const visible = row.querySelector('select[data-field="visible"]');
            if (field === 'timeopen' && visible && !visible.disabled && visible.value === '0') {
                setValue(visible, '1');
            }
            syncReview(row);
        });
        form.requestSubmit();
    };
    form.querySelector('[data-action="opennow"]').addEventListener('click', () => setNow('timeopen'));
    form.querySelector('[data-action="closenow"]').addEventListener('click', () => setNow('timeclose'));

    // Review before saving: list every change, and save only once confirmed.
    const columnLabel = (field) => form.querySelector(`th[data-col="${field}"]`)?.dataset.label ?? field;
    const shownValue = (control, value, none) => {
        if (control.tagName === 'SELECT') {
            const option = [...control.options].find((o) => o.value === value);
            return option ? option.textContent.trim() : value;
        }
        return value === '' ? none : value.replace('T', ' ');
    };
    let confirmed = false;
    form.addEventListener('submit', async(e) => {
        if (confirmed) {
            return;
        }
        e.preventDefault();
        const strings = await getStrings([
            'confirmtitle', 'confirmsave', 'confirmnone', 'confirmreview', 'confirmgrade', 'confirmattempts', 'nochanges',
        ].map((key) => ({key, component: 'local_quizbulkedit'})));
        const [title, save, none, reviewchanged, gradewarning, attemptswarning, nochanges] = strings;

        let count = 0;
        let quizzes = 0;
        const warnings = new Set();
        let list = '';
        quizRows.forEach((row) => {
            const changed = [...row.querySelectorAll('[data-original]')]
                .filter((control) => !control.disabled && control.value !== control.dataset.original);
            if (!changed.length) {
                return;
            }
            quizzes++;
            let items = '';
            if (changed.some((control) => control.dataset.review)) {
                items += `<li>${escapeHtml(reviewchanged)}</li>`;
                count++;
            }
            changed.filter((control) => !control.dataset.review).forEach((control) => {
                const field = control.dataset.field;
                items += `<li>${escapeHtml(columnLabel(field))}: ` +
                    `<del>${escapeHtml(shownValue(control, control.dataset.original, none))}</del> → ` +
                    `<strong>${escapeHtml(shownValue(control, control.value, none))}</strong></li>`;
                count++;
                if (field === 'grade') {
                    warnings.add(gradewarning);
                }
                if (['timeclose', 'timelimit', 'overduehandling', 'graceperiod'].includes(field)) {
                    warnings.add(attemptswarning);
                }
            });
            const name = row.querySelector('.local-quizbulkedit-sticky2 a').textContent.trim();
            list += `<li><strong>${escapeHtml(name)}</strong><ul>${items}</ul></li>`;
        });

        if (!count) {
            addToast(nochanges, {type: 'info'});
            return;
        }
        const summary = await getString('confirmsummary', 'local_quizbulkedit', {settings: count, quizzes});
        const body = `<p>${escapeHtml(summary)}</p><ul class="mb-2">${list}</ul>` +
            [...warnings].map((warning) => `<div class="alert alert-warning py-2 mb-2">${escapeHtml(warning)}</div>`).join('');
        const modal = await ModalSaveCancel.create({title, body, buttons: {save}, show: true, removeOnClose: true});
        modal.getRoot().on(ModalEvents.save, () => {
            confirmed = true;
            form.requestSubmit();
        });
    });
};
